<template><div class="page"><div class="welcome"><div><span class="muted">今日经营数据</span><h2>欢迎回来，{{username}}</h2><p class="muted">甜品、订单与库存均来自实时 MySQL 数据库。</p></div><el-button type="primary" @click="$router.push('/orders')">创建订单</el-button></div><el-skeleton :loading="loading" animated :rows="5"><template #default><div v-if="error" class="panel">{{error}}</div><template v-else><div class="metrics"><article v-for="m in metrics" :key="m.label" class="metric"><span>{{m.icon}}</span><div><strong>{{m.value}}</strong><small>{{m.label}}</small></div></article></div><div class="grid"><section class="panel"><h3>最近订单</h3><el-empty v-if="!summary.recentOrders?.length" description="暂无订单"/><div v-for="o in summary.recentOrders" :key="o.id" class="row"><div><strong>{{o.orderNo}}</strong><small>{{o.customerName}}</small></div><span>¥{{Number(o.totalAmount).toFixed(2)}}</span><el-tag>{{o.status}}</el-tag></div></section><section class="panel"><h3>低库存提醒</h3><el-empty v-if="!summary.lowStockDesserts?.length" description="库存状态良好"/><div v-for="d in summary.lowStockDesserts" :key="d.id" class="row"><strong>{{d.name}}</strong><el-tag type="danger">{{d.stock}} 件</el-tag></div></section></div></template></template></el-skeleton></div></template>
<script setup>import{computed,onMounted,reactive,ref}from'vue';import{getDashboardSummary}from'../api/dashboard';const loading=ref(true),error=ref(''),summary=reactive({}),username=JSON.parse(sessionStorage.getItem('currentUser')||'{}').username||'管理员';const metrics=computed(()=>[{label:'甜品总数',value:summary.dessertCount||0,icon:'🍮'},{label:'今日订单',value:summary.todayOrderCount||0,icon:'▤'},{label:'今日销售额',value:`¥${Number(summary.todaySalesAmount||0).toFixed(2)}`,icon:'¥'},{label:'低库存项目',value:summary.lowStockCount||0,icon:'!'}]);async function load(){loading.value=true;try{Object.assign(summary,await getDashboardSummary())}catch(e){error.value=e.message}finally{loading.value=false}}onMounted(load)</script>
<style scoped>.welcome{padding:10px 4px;display:flex;justify-content:space-between;align-items:end}.welcome h2{font-family:Georgia,serif;font-size:31px;margin:7px 0}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}.metric{display:flex;gap:16px;align-items:center;padding:22px;background:linear-gradient(145deg,#2b1f1b,#211815);border:1px solid var(--border);border-radius:16px}.metric>span{display:grid;place-items:center;width:46px;height:46px;border-radius:13px;background:#3b2b22;color:var(--amber);font-size:21px}.metric strong,.metric small{display:block}.metric strong{font-size:25px;color:var(--amber-strong)}.metric small,.row small{margin-top:4px;color:var(--muted)}.grid{display:grid;grid-template-columns:1.3fr 1fr;gap:18px}.row{display:flex;align-items:center;gap:12px;padding:13px 0;border-bottom:1px solid var(--border)}.row div{flex:1}.row small{display:block}@media(max-width:1050px){.metrics{grid-template-columns:repeat(2,1fr)}.grid{grid-template-columns:1fr}}@media(max-width:600px){.metrics{grid-template-columns:1fr}}</style>
